+  idempotency_key_required: {
+    message:
+      "The app did not send a request key. Update the app; contact support if it keeps happening.",
+  },
+  IDEMPOTENCY_CONFLICT: {
+    message:
+      "A previous attempt of this action is still finishing. Wait a few seconds, then reload.",
+    reload: true,
+  },
+  ASSET_ALREADY_IN_PACKAGE: {
+    message: "This program is already in that package.",
+    reload: true,
+  },
+  ASSET_NOT_FOUND: {
+    message:
+      "The package could not find this program. Reload and pick it again; contact support if it persists.",
+    reload: true,
+  },
+  NOT_YOUR_PACKAGE: { message: "That package belongs to another coach." },
+  PACKAGE_NOT_FOUND: {
+    message: "That package was removed. Reload the package list.",
+    reload: true,
+  },
+  // Raised by programsApi.assignableClients (RosterIncompleteError).
+  client_roster_incomplete: {
+    message:
+      "Your full client list did not load, so no clients are shown yet. Retry; if it keeps happening, contact support (Settings, Help).",
+  },
+};
+
+interface ErrorEnvelope {
+  status: number | null;
+  code: string | null;
+  message: string | null;
+}
+
+function readEnvelope(err: unknown): ErrorEnvelope {
+  if (!err || typeof err !== "object")
+    return { status: null, code: null, message: null };
+  const response = (err as { response?: { status?: unknown; data?: unknown } })
+    .response;
+  if (!response) {
+    // A failure the app raised itself (no HTTP answer) may carry its own
+    // known code, e.g. the incomplete client roster.
+    const own = (err as { code?: unknown }).code;
+    if (typeof own === "string" && Object.prototype.hasOwnProperty.call(KNOWN, own))
+      return { status: null, code: own, message: null };
+  }
+  const status = typeof response?.status === "number" ? response.status : null;
+  const data = response?.data;
+  let code: string | null = null;
+  let message: string | null = null;
+  if (data && typeof data === "object") {
+    const d = data as { code?: unknown; error?: unknown; message?: unknown };
+    if (typeof d.code === "string" && d.code !== "") code = d.code;
+    else if (typeof d.error === "string" && /^[A-Za-z_]+$/.test(d.error))
+      code = d.error;
+    if (typeof d.message === "string") message = d.message;
+    else if (Array.isArray(d.message)) {
+      // Nest DTO validation sends a list of field messages.
+      const parts = d.message.filter(
+        (m): m is string => typeof m === "string" && m !== "",
+      );
+      if (parts.length > 0) message = parts.join("; ");
+    }
+  }
+  return { status, code, message };
+}
+
+function shortRef(full: string): string {
+  return (
+    full
+      .replace(/[^A-Za-z0-9]/g, "")
+      .slice(0, 8)
+      .toUpperCase() || "UNKNOWN"
+  );
+}
+
+/**
+ * Describe a failed Programs action. `action` is a short verb phrase used in
+ * the unknown-failure copy and the Sentry event ("assign the program").
+ */
+export function describeProgramFailure(
+  err: unknown,
+  action: string,
+): ProgramFailure {
+  const env = readEnvelope(err);
+  const known = env.code ? KNOWN[env.code] : undefined;
+  if (known) {
+    return {
+      code: env.code,
+      status: env.status,
+      message: known.message,
+      reference: null,
+      support:
+        env.code === "programs_unavailable" ||
+        env.code === "idempotency_key_required" ||
+        env.code === "program_in_clinic_set" ||
+        env.code === "program_in_clinic_set_needs_a_day" ||
+        env.code === "client_roster_incomplete",
+      reload: known.reload === true,
+    };
+  }
+  if (env.status === 401) {
+    return {
+      code: env.code,
+      status: 401,
+      message: `Could not ${action}: your session has ended. Sign in again to carry on; anything already saved is kept.`,
+      reference: null,
+      support: false,
+      reload: false,
+      recovery: "sign_in",
+    };
+  }
+  if (env.status === 429) {
+    return {
+      code: env.code,
+      status: 429,
+      message: `Could not ${action}: too many requests in a short time. Wait a minute, then retry.`,
+      reference: null,
+      support: false,
+      reload: false,
+      recovery: "wait",
+    };
+  }
+  const isNetwork =
+    !!err &&
+    typeof err === "object" &&
+    !(err as { response?: unknown }).response;
+  const full = extractRequestId(err) ?? randomUuid();
+  const reference = shortRef(full);
+  captureError(err, {
+    area: "programs",
+    action,
+    status: env.status,
+    code: env.code,
+    reference: full,
+  });
+  if (isNetwork) {
+    return {
+      code: null,
+      status: null,
+      message: `Could not ${action}: the app could not reach the server. Check your connection and retry. Reference ${reference}.`,
+      reference,
+      support: true,
+      reload: false,
+    };
+  }
+  if (env.status === 403) {
+    return {
+      code: env.code,
+      status: 403,
+      message: `Could not ${action}: your account does not have access to this. If you think it should, contact support and quote reference ${reference}.`,
+      reference,
+      support: true,
+      reload: false,
+    };
+  }
+  if (env.status === 404) {
+    return {
+      code: env.code,
+      status: 404,
+      message: `Could not ${action}: it no longer exists or is not shared with you. Reload to see the current list; if it should be there, contact support and quote reference ${reference}.`,
+      reference,
+      support: true,
+      reload: true,
+    };
+  }
+  if (
+    env.message &&
+    env.status !== null &&
+    env.status >= 400 &&
+    env.status < 500
+  ) {
+    // A definite refusal with a reason this app does not have copy for yet
+    // (DTO validation, or a 409 / 422 business rule added after this build,
+    // S-MWB-3 C-328-7). Show the server's reason, and keep the reference and
+    // support path in case the app sent it.
+    return {
+      code: env.code,
+      status: env.status,
+      message: `Could not ${action}: ${env.message.replace(/[.\s]+$/, "")}. If this keeps happening, contact support and quote reference ${reference}.`,
+      reference,
+      support: true,
+      reload: false,
+    };
+  }
+  return {
+    code: env.code,
+    status: env.status,
+    message: `Could not ${action} because of a problem on the server. Retry; if it happens again, contact support and quote reference ${reference}.`,
+    reference,
+    support: true,
+    reload: false,
+  };
+}
+
+/** Per-client bulk-assign outcome copy (server message wins when present). */
+export function bulkResultCopy(
+  code: string | undefined,
+  serverMessage: string | undefined,
+): string {
+  if (code && KNOWN[code]) return KNOWN[code].message;
+  if (serverMessage) return serverMessage;
+  return "Not assigned. Retry this client; contact support if it fails again.";
+}
